/**
 * 辅助函数: 生成基于基准价格和特征波动率的历史K线数据 (130个交易日，满足120日K线上下限计算)
 */
function generateHistory(basePrice: number, dailyVolPercent: number, trend: number = 0): DailyCandle[] {
  const candles: DailyCandle[] = [];
  let current = basePrice * (1 - trend * 0.08);

  const dates: string[] = [];
  const now = new Date();
  for (let i = 185; i >= 0; i--) {
    const d = new Date(now);
    d.setDate(d.getDate() - i);
    // 排除周末
    if (d.getDay() !== 0 && d.getDay() !== 6) {
      dates.push(d.toISOString().slice(5, 10)); // MM-DD
    }
  }

  // 保证取130天
  while (dates.length < 130) {
    dates.unshift(`05-${dates.length + 1}`);
  }

  // 伪随机种子稳定历史
  let seed = Math.round(basePrice * 1000);
  function pseudoRandom() {
    seed = (seed * 9301 + 49297) % 233280;
    return seed / 233280;
  }

  for (let i = 0; i < 130; i++) {
    const changeFactor = (pseudoRandom() - 0.48) * dailyVolPercent * 0.02;
    const open = current;
    const close = Number((open * (1 + changeFactor)).toFixed(3));
    const range = Math.max(0.008, Math.abs(close - open) + pseudoRandom() * basePrice * dailyVolPercent * 0.015);
    const high = Number((Math.max(open, close) + range * (0.3 + pseudoRandom() * 0.5)).toFixed(3));
    const low = Number((Math.min(open, close) - range * (0.2 + pseudoRandom() * 0.4)).toFixed(3));

    candles.push({
      date: dates[i] || `D-${130 - i}`,
      open,
      high,
      low,
      close,
    });

    current = close;
  }

  return candles;
}

