/**
 * 初始化并生成完整计算好的 ETF 列表
 */
export function getInitialEtfList(period: AtrPeriod = 14): EtfItem[] {
  return RAW_ETFS.map((raw) => {
    const change = Number((raw.price - raw.prevClose).toFixed(3));
    const changePercent = Number(((change / raw.prevClose) * 100).toFixed(2));
    const history = generateHistory(raw.price, raw.dailyVolPercent, changePercent > 0 ? 1 : -1);

    // 确保历史最后一根与当天的 high/low/close 对应
    if (history.length > 0) {
      history[history.length - 1] = {
        date: '今日',
        open: raw.prevClose,
        high: raw.high,
        low: raw.low,
        close: raw.price,
      };
    }

    return enrichEtfItem(
      {
        id: raw.id,
        code: raw.code,
        name: raw.name,
        category: classifyEtfByName(raw.name, raw.code, raw.category),
        price: raw.price,
        change,
        changePercent,
        high: raw.high,
        low: raw.low,
        prevClose: raw.prevClose,
        volumeAmount: raw.volumeAmount,
        scaleText: raw.scaleText,
        scaleAmount: raw.scaleText ? parseFloat(raw.scaleText.replace(/[^0-9.]/g, '')) || undefined : undefined,
        history,
        selected: true,
      },
      period
    );
  });
}
